export function sanitizeBannerImages(images?: string[], legacyBannerUrl?: string): string[] {
  const cleaned = Array.isArray(images)
    ? images.map((u) => (typeof u === 'string' ? u.trim() : '')).filter(Boolean)
    : [];
  if (cleaned.length > 0) {
    return cleaned.slice(0, 4);
  }
  const single = typeof legacyBannerUrl === 'string' ? legacyBannerUrl.trim() : '';
  return single ? [single] : [];
}
